<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{listarTareas,recibirTarea,type Option,type Tarea}from'@/modules/evan/catastro/services/tareas'
const props=defineProps<{area:string;areaNombre:string;descripcion:string;color?:string}>();const rows=ref<Tarea[]>([]),districts=ref<Option[]>([]),types=ref<Option[]>([]),total=ref(0),last=ref(1),loading=ref(false),receiving=ref(0),error=ref(''),success=ref('');const filters=reactive({criterio:'',distrito_id:0,tipo_atencion_id:0,page:1});async function load(p=1){filters.page=p;loading.value=true;error.value='';try{const r=await listarTareas(filters,props.area);rows.value=r.data;total.value=r.total;last.value=r.last_page;districts.value=r.distritos;types.value=r.tipos_atencion}catch(e){error.value=e instanceof Error?e.message:'No se pudo cargar la bandeja.'}finally{loading.value=false}}async function receive(x:Tarea){if(!confirm(`¿Recibir la tarea #${x.id} del ticket #${x.ticket_id}?`))return;receiving.value=x.id;try{await recibirTarea(x.id,props.area);success.value='Tarea recibida correctamente.';await load(filters.page)}catch(e){error.value=e instanceof Error?e.message:'No se pudo recibir la tarea.'}finally{receiving.value=0}}function clear(){Object.assign(filters,{criterio:'',distrito_id:0,tipo_atencion_id:0});load()}onMounted(()=>load())
</script>
<template><div class="page" :style="{'--a':color||'#716098'}"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / {{areaNombre}} / Tareas</nav><header class="hero"><div class="mark">TA</div><div><small>EVAN · {{areaNombre.toUpperCase()}}</small><h1>Tareas por recibir</h1><p>{{descripcion}}</p></div><strong>{{total}} pendientes</strong></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="filters"><label>Ticket o tarea<input v-model.trim="filters.criterio" placeholder="Número" @keyup.enter="load()"></label><label>Distrito<select v-model.number="filters.distrito_id"><option :value="0">Todos</option><option v-for="x in districts" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Tipo de atención<select v-model.number="filters.tipo_atencion_id"><option :value="0">Todos</option><option v-for="x in types" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><div><button @click="load()">Consultar</button><button class="clear" @click="clear">Limpiar</button></div></section><div v-if="loading" class="empty">Cargando tareas de {{areaNombre}}…</div><div v-else-if="!rows.length" class="empty">No existen tareas pendientes de recepción.</div><section v-else class="table"><header><span>Tarea / Ticket</span><span>Tipo de atención</span><span>Cliente</span><span>Ubicación</span><span>Remitente</span><span>Acción</span></header><article v-for="x in rows" :key="x.id"><div><b>#{{x.id}}</b><small>Ticket #{{x.ticket_id}} · {{x.fecha}}</small></div><div><b>{{x.tipo_tarea}}</b><small>{{x.tipo_atencion}}</small></div><div><b>{{x.cliente}}</b><small>{{x.documento||'—'}}</small></div><div><b>{{x.distrito}}</b><small>{{x.direccion||'—'}}</small></div><div><b>{{x.usuario_envia}}</b><small>{{x.estado}}</small></div><button :disabled="receiving===x.id" @click="receive(x)">{{receiving===x.id?'Recibiendo…':'Recibir'}}</button></article></section><footer v-if="last>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{last}}</span><button :disabled="filters.page>=last" @click="load(filters.page+1)">Siguiente</button></footer></div></template>
<style scoped>
.page{color:#37464d}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:800}.hero small{color:var(--a);font-size:.52rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.28rem}.hero p{margin:0;color:#7c898f;font-size:.62rem}.hero strong{margin-left:auto;font-size:.52rem}.flash{padding:10px;font-size:.6rem}.good{color:#267359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:grid;grid-template-columns:1fr 1fr 1.3fr auto;align-items:end;gap:8px;background:#fff}.filters label{font-size:.47rem}input,select{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;font:inherit;font-size:.52rem}.filters button,.pages button,.table article>button{padding:8px 10px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.47rem}.filters .clear{margin-left:4px;color:#68767c;background:#edf1f2}.table{margin-top:12px;background:#fff}.table>header,.table>article{padding:9px 12px;display:grid;grid-template-columns:.7fr 1.2fr 1.1fr 1.2fr 1fr .55fr;align-items:center;gap:8px;border-bottom:1px solid #e9edee}.table>header{color:#849096;background:#f4f6f7;font-size:.42rem}.table article{font-size:.47rem}.table article b,.table article small{display:block}.table article small{color:#89949a;font-size:.4rem}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.58rem}.pages{display:flex;justify-content:center;align-items:center;gap:8px;font-size:.48rem}@media(max-width:800px){.filters{grid-template-columns:1fr 1fr}.table>header{display:none}.table>article{grid-template-columns:1fr 1fr}}@media(max-width:520px){.hero{flex-wrap:wrap}.hero strong{margin-left:0}.filters,.table>article{grid-template-columns:1fr}}
</style>
